import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"一、一次请求在 Spring MVC 里经过了什么","description":"","frontmatter":{"title":"一、一次请求在 Spring MVC 里经过了什么"},"headers":[{"level":3,"title":"1.1 过滤器与拦截器怎么选","slug":"_1-1-过滤器与拦截器怎么选","link":"#_1-1-过滤器与拦截器怎么选","children":[]},{"level":3,"title":"1.2 不要用 @EnableWebMvc","slug":"_1-2-不要用-enablewebmvc","link":"#_1-2-不要用-enablewebmvc","children":[]}],"relativePath":"ch04/01.md","filePath":"ch04/01.md","lastUpdated":1789497795000}'),p={name:"ch04/01.md"};function i(l,a,r,d,c,o){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="一、一次请求在-spring-mvc-里经过了什么" tabindex="-1">一、一次请求在 Spring MVC 里经过了什么 <a class="header-anchor" href="#一、一次请求在-spring-mvc-里经过了什么" aria-label="Permalink to &quot;一、一次请求在 Spring MVC 里经过了什么&quot;">​</a></h1><p>理解这条链路，后面所有配置项才知道该往哪儿放。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  │  HTTP 请求</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Servlet 容器（Tomcat 11）                    │</span></span>
<span class="line"><span>│   Filter 链  ← Servlet 规范，拿不到 Handler  │</span></span>
<span class="line"><span>│      │                                       │</span></span>
<span class="line"><span>│      ▼                                       │</span></span>
<span class="line"><span>│   DispatcherServlet  ← Spring MVC 的前端控制器│</span></span>
<span class="line"><span>│      │                                       │</span></span>
<span class="line"><span>│      ├─ HandlerMapping  找到该由哪个方法处理   │</span></span>
<span class="line"><span>│      ├─ HandlerInterceptor.preHandle         │</span></span>
<span class="line"><span>│      ├─ HandlerAdapter 调用 Controller 方法   │</span></span>
<span class="line"><span>│      ├─ HandlerInterceptor.postHandle        │</span></span>
<span class="line"><span>│      ├─ 返回值交给 HttpMessageConverter 序列化 │</span></span>
<span class="line"><span>│      └─ HandlerInterceptor.afterCompletion   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span>
<span class="line"><span>  │  HTTP 响应</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>浏览器</span></span></code></pre></div><p>启动日志里能看到 DispatcherServlet 的初始化——它是在<strong>第一个请求到达时</strong>才初始化的，不是启动时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026-09-13T16:43:58.355+08:00  INFO 88035 --- [activity-server] [nio-8080-exec-1] o.s.web.servlet.DispatcherServlet : Initializing Servlet &#39;dispatcherServlet&#39;</span></span>
<span class="line"><span>2026-09-13T16:43:58.356+08:00  INFO 88035 --- [activity-server] [nio-8080-exec-1] o.s.web.servlet.DispatcherServlet : Completed initialization in 1 ms</span></span></code></pre></div><p>想让它在启动时就初始化（提前暴露配置错误、避免首请求变慢），加上配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mvc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    servlet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      load-on-startup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="_1-1-过滤器与拦截器怎么选" tabindex="-1">1.1 过滤器与拦截器怎么选 <a class="header-anchor" href="#_1-1-过滤器与拦截器怎么选" aria-label="Permalink to &quot;1.1 过滤器与拦截器怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Filter</th><th>HandlerInterceptor</th></tr></thead><tbody><tr><td>所属规范</td><td>Servlet（<code>jakarta.servlet</code>）</td><td>Spring MVC（<code>org.springframework.web.servlet</code>）</td></tr><tr><td>能拿到什么</td><td>请求、响应</td><td>还能拿到 <code>HandlerMethod</code>，知道要调哪个类的哪个方法</td></tr><tr><td>典型用途</td><td>编码、跨域、请求包装、安全过滤链</td><td>日志、鉴权、参数预处理、多租户上下文</td></tr><tr><td>注册方式</td><td><code>@Component</code> 或 <code>FilterRegistrationBean</code></td><td>实现 <code>WebMvcConfigurer#addInterceptors</code></td></tr></tbody></table><p><strong>判断标准</strong>：需要知道“要执行哪个方法”就用拦截器；需要在 MVC 之外生效（比如静态资源、错误页）就用过滤器。</p><h3 id="_1-2-不要用-enablewebmvc" tabindex="-1">1.2 不要用 @EnableWebMvc <a class="header-anchor" href="#_1-2-不要用-enablewebmvc" aria-label="Permalink to &quot;1.2 不要用 @EnableWebMvc&quot;">​</a></h3><p>这是新手最容易踩的坑之一。<code>@EnableWebMvc</code> 会<strong>关掉 Spring Boot 的全部 MVC 自动配置</strong>，此后静态资源映射、消息转换器、参数解析器、错误处理全都要自己重配。正确做法是实现 <code>WebMvcConfigurer</code>——它只加东西，不改默认行为。</p>`,12)])])}const v=s(p,[["render",i]]);export{g as __pageData,v as default};
